type Token = { kind: 'cmd'; name: string } | { kind: 'char'; text: string }

function tokenize(tex: string): Token[] {
  const chars = [...tex]
  const tokens: Token[] = []

  for (let i = 0; i < chars.length; i++) {
    const char = chars[i] ?? ''

    if (char !== '\\') {
      tokens.push({ kind: 'char', text: char })
      continue
    }

    const next = chars[i + 1]

    if (next === undefined) {
      break
    }

    if (!/[A-Za-z]/.test(next)) {
      tokens.push({ kind: 'cmd', name: next })
      i++
      continue
