function restyle(node: MathNode, change: (node: Sym) => Sym): MathNode {
  switch (node.kind) {
    case 'sym':
      return change(node)
    case 'row':
      return { ...node, items: node.items.map(item => restyle(item, change)) }
    case 'scripts':
      return { ...node, base: restyle(node.base, change) }
    case 'accent':
      return { ...node, body: restyle(node.body, change) }
    default:
