    return { kind: 'grid', rows, align: rows.some(cells => cells.length > 1) ? 'pairs' : 'center' }
  }

  private peek(): Token | undefined {
    return this.tokens[this.at]
  }

  private take(): Token | undefined {
    const token = this.tokens[this.at]
    this.at++

